package com.mcnex.conversation;
import android.content.Context;import android.view.*;import android.widget.*;
final class SwipeMeetingCard extends FrameLayout {
 private final View card;private final int distance,slop;private float x,y,start;private boolean dragging;private int opened;private final LinearLayout actions;
 SwipeMeetingCard(Context c,View card,Runnable open,Runnable delete,Runnable share){super(c);this.card=card;distance=(int)(96*c.getResources().getDisplayMetrics().density);slop=ViewConfiguration.get(c).getScaledTouchSlop();actions=new LinearLayout(c);actions.setGravity(Gravity.CENTER_VERTICAL);ImageButton action=new ImageButton(c);int iconSize=(int)(52*c.getResources().getDisplayMetrics().density);LinearLayout.LayoutParams iconLp=new LinearLayout.LayoutParams(iconSize,iconSize);iconLp.setMargins((distance-iconSize)/2,0,(distance-iconSize)/2,0);action.setPadding(iconSize/4,iconSize/4,iconSize/4,iconSize/4);action.setScaleType(ImageView.ScaleType.CENTER_INSIDE);actions.addView(action,iconLp);addView(actions,new FrameLayout.LayoutParams(-1,-1));addView(card,new FrameLayout.LayoutParams(-1,-2));card.setOnClickListener(v->{if(opened!=0)show(0);else open.run();});setTag(action);}

 private Runnable remove,send;
 void bind(Runnable delete,Runnable share){remove=delete;send=share;}
 private void style(ImageButton button,int direction){button.setImageResource(direction<0?R.drawable.trash_2:R.drawable.share_2);button.setColorFilter(direction<0?0xffa33232:0xffffffff);android.graphics.drawable.GradientDrawable background=new android.graphics.drawable.GradientDrawable();background.setShape(android.graphics.drawable.GradientDrawable.OVAL);background.setColor(direction<0?0xfff8dfdc:0xff242424);button.setBackground(background);button.setContentDescription(direction<0?"회의 기록 삭제":"회의록 공유 앱 선택");}
 private void show(int direction){opened=direction;ImageButton button=(ImageButton)getTag();style(button,direction);actions.setGravity((direction<0?Gravity.RIGHT:Gravity.LEFT)|Gravity.CENTER_VERTICAL);button.setOnClickListener(v->{if(opened<0)remove.run();else if(opened>0)send.run();});card.animate().translationX(direction*distance).setDuration(160).start();}
 @Override public boolean onInterceptTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();start=card.getTranslationX();dragging=false;}else if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&Math.abs(e.getX()-x)>slop*2&&Math.abs(e.getX()-x)>Math.abs(e.getY()-y)*1.4){dragging=true;getParent().requestDisallowInterceptTouchEvent(true);onTouchEvent(e);return true;}return false;}
 @Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&dragging){float dx=e.getX()-x;card.setTranslationX(Math.max(-distance,Math.min(distance,start+dx)));ImageButton button=(ImageButton)getTag();int direction=card.getTranslationX()<0?-1:1;style(button,direction);actions.setGravity((direction<0?Gravity.RIGHT:Gravity.LEFT)|Gravity.CENTER_VERTICAL);return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP&&dragging){float value=card.getTranslationX();show(Math.abs(value)>distance*.4?(value<0?-1:1):0);dragging=false;return true;}if(e.getActionMasked()==MotionEvent.ACTION_CANCEL){show(opened);dragging=false;return true;}return true;}
}
